package com.crm.hr;
import com.crm.hr.service.*;import com.crm.hr.service.impl.LeaveServiceImpl;import com.crm.hr.repository.LeaveRepository;import com.crm.hr.mapper.LeaveMapper;import com.crm.hr.entity.LeaveRequest;import com.crm.hr.dto.LeaveRequestDto;import java.util.*;import org.junit.jupiter.api.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class LeaveCalendarPolicyTest {
 final LeaveRepository repository=mock(LeaveRepository.class);final LeaveAccess access=mock(LeaveAccess.class);final LeaveServiceImpl service=new LeaveServiceImpl(repository,new LeaveMapper(),access);
 @Test void calendarFiltersInRepositoryAndKeepsInclusiveDates(){service.calendar(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO," 101 ");var order=inOrder(access,repository);order.verify(access).requireAdmin();order.verify(repository).calendar(eq(LeaveBalanceCalculationTest.FROM),eq(LeaveBalanceCalculationTest.TO),eq("101"),argThat(p->p.getPageSize()==5001));verify(repository,never()).findAll();}
 @Test void noEmployeeFilterIsExplicitNull(){service.calendar(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO,"");verify(repository).calendar(any(),any(),isNull(),any());}
 @Test void invalidRangeDoesNotLoadTable(){assertThrows(IllegalArgumentException.class,()->service.calendar(LeaveBalanceCalculationTest.TO,LeaveBalanceCalculationTest.FROM,null));verifyNoInteractions(repository);}
 @Test void forbiddenCalendarDoesNotRead(){doThrow(new org.springframework.security.access.AccessDeniedException("Forbidden")).when(access).requireAdmin();assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.calendar(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO,null));verifyNoInteractions(repository);}
 @Test void oversizedCalendarIsRejectedInsteadOfTruncated(){when(repository.calendar(any(),any(),any(),any())).thenReturn(Collections.nCopies(5001,new LeaveRequest()));assertThrows(IllegalArgumentException.class,()->service.calendar(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO,"101"));}
 @Test void approvedLeaveCannotBeChangedOrDeletedToChangeItsBalance(){var row=new LeaveRequest();row.setId(1L);row.setEmployeeId("101");row.setStatus(LeaveRequest.LeaveStatus.APPROVED);when(repository.findById(1L)).thenReturn(Optional.of(row));var request=new LeaveRequestDto();request.setEmployeeId("101");assertThrows(IllegalArgumentException.class,()->service.updateLeave(1L,request));assertThrows(IllegalArgumentException.class,()->service.deleteLeave(1L));verify(repository,never()).save(any());verify(repository,never()).delete(any(LeaveRequest.class));}
}